{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_PandL as select SALEORDERITEMCODE ,a.source as Marketing_Source ,(a.channel) as Marketing_Channel ,a.marketplace ,a.FINAL_MARKETPLACE ,(a.order_Date::date) as Date ,a.order_id ,a.reference_code ,a.shop_name ,a.return_flag ,location_key ,a.new_customer_flag ,a.customer_id_final ,payment_mode ,payment_gateway ,a.awb ,a.order_Status ,a.shipping_status ,a.final_shipping_status ,case when lower(order_Status) like \'%cancel%\' then upper(order_status) else upper(coalesce(final_shipping_status,order_status)) end final_status ,a.sku ,(a.sku_code) sku_code ,a.common_sku_code ,a.product_name_final PRODUCT_NAME_FINAL ,a.product_sub_category product_sub_category ,a.product_category PRODUCT_CATEGORY ,a.quantity ,PRE_QUANTITY ,d.gst ,case when lower(ifnull(payment_gateway_name,\'\')) like \'%razorpay%\' and lower(FINAL_MARKETPLACE) like \'%website%\' then (ifnull(selling_price,0) * 0.03) when lower(ifnull(payment_gateway_name,\'\')) like \'%snapmint%\' and lower(FINAL_MARKETPLACE) like \'%website%\' then (ifnull(selling_price,0) * 0.04) else a.return_amount end as return_amount ,a.total_mrp ,a.selling_price ,a.shipping_price shipping_price ,d.cogs as test_cogs ,(ifnull(d.cogs,0)*ifnull(PRE_QUANTITY,0)) as forwardCogs ,(ifnull(d.cogs,0)*ifnull(ex_RETURNED_QUANTITY,0)) + ifnull(case when lower(ifnull(payment_gateway_name,\'\')) like \'%razorpay%\' and lower(FINAL_MARKETPLACE) like \'%website%\' then ((ifnull(d.cogs,0)*ifnull(PRE_QUANTITY,0)) * 0.03) when lower(ifnull(payment_gateway_name,\'\')) like \'%snapmint%\' and lower(FINAL_MARKETPLACE) like \'%website%\' then ((ifnull(d.cogs,0)*ifnull(PRE_QUANTITY,0)) * 0.04) end,0) returnCogs ,(case when lower(a.type) like \'%sale%\' then (ifnull(d.cogs,0)*ifnull(PRE_QUANTITY,0)) else -1*(ifnull(d.cogs,0)*ifnull(ex_RETURNED_QUANTITY,0)) end) -ifnull(case when lower(ifnull(payment_gateway_name,\'\')) like \'%razorpay%\' and lower(FINAL_MARKETPLACE) like \'%website%\' then ((ifnull(d.cogs,0)*ifnull(PRE_QUANTITY,0)) * 0.03) when lower(ifnull(payment_gateway_name,\'\')) like \'%snapmint%\' and lower(FINAL_MARKETPLACE) like \'%website%\' then ((ifnull(d.cogs,0)*ifnull(PRE_QUANTITY,0)) * 0.04) end,0) as COGS ,a.tax tax ,a.RETURN_TAX ,a.type ,div0(ifnull(spend,0), count(*) over(partition by order_date,lower(a.FINAL_Mapped_Marketplace),lower(a.type))) as Spend ,case when a.new_customer_flag = \'Repeat\' then LAG(a.order_date) IGNORE NULLS OVER (partition by a.customer_id_final ORDER BY a.order_date) end previous_date ,datediff(day,previous_date,a.order_Date) days_from_last_order ,otherShipmentCost ,logisticCost ,paymentgatewaycharges ,marketplaceCommission ,div0(ifnull(EBO_Rent,0),count(*) over(partition by lower(location_key),last_day(to_date(a.order_date)),lower(a.type))) as EBO_Rent ,div0(ifnull(EBO_salary,0),count(*) over(partition by lower(location_key),last_day(to_date(a.order_date)),lower(a.type))) as EBO_salary ,div0(ifnull(EBO_overhead,0),count(*) over(partition by lower(location_key),last_day(to_date(a.order_date)),lower(a.type))) as EBO_overhead ,FINAL_Mapped_Marketplace ,a.EBO_Store from ( select *, Marketplace_Mapped as FINAL_Mapped_Marketplace, upper(case when lower(Marketplace_Mapped) like \'%amazon%\' then \'AMAZON\' when lower(Marketplace_Mapped) like \'%flipkart%\' then \'FLIPKART\' when lower(Marketplace_Mapped) like any (\'%website%\') then \'WEBSITE\' when lower(Marketplace_Mapped) like \'%myntra%\' then \'MYNTRA\' when lower(Marketplace_Mapped) like \'%pepperfry%\' then \'PEPPERFRY\' when lower(Marketplace_Mapped) like \'%ebo%\' then \'EBO\' else \'OTHERS\' END) as FINAL_MARKETPLACE, upper(case when lower(Marketplace_Mapped) like \'%amazon%\' then \'AMAZON\' when lower(Marketplace_Mapped) like \'%flipkart%\' then \'FLIPKART\' when lower(Marketplace_Mapped) like any (\'%website%\') then \'WEBSITE\' when lower(Marketplace_Mapped) like any (\'%zepto%\',\'%instamart%\',\'%blinkit%\') then \'QC\' when lower(Marketplace_Mapped) like any (\'%ebo%\') then \'EBO\' else marketplace END) as FINAL_MARKETPLACE_shipment_costs ,store_name as EBO_Store from(SELECT *, upper(case when lower(shop_name) like \'%amazon%\' then \'AMAZON\' when lower(shop_name) like \'%flipkart%\' then \'FLIPKART\' when lower(shop_name) like \'%myntra%\' then \'MYNTRA\' when lower(shop_name) like \'%queuebuster%\' then \'EBO\' when lower(shop_name) like any (\'%shopify%\',\'%woocommerce%\') and lower(ifnull(payment_gateway_name,\'\')) like any (\'%snapmint%\',\'%razorpay%\',\'%cred%\',\'%bharatxpay%\') and lower(shop_name) like any (\'%shopify%\',\'%woocommerce%\') then \'WEBSITE\' when lower(shop_name) like any (\'%offline%\',\'%b2b%\') and lower(replace(reference_code,\'_\',\'&\')) like \'%&p%\' then \'PEPPERFRY\' when lower(shop_name) like any (\'%offline%\',\'%b2b%\') and lower(replace(reference_code,\'_\',\'&\')) like \'%&zp%\' then \'ZEPTO\' when lower(shop_name) like any (\'%offline%\',\'%b2b%\') and lower(replace(reference_code,\'_\',\'&\')) like \'%&mart%\' then \'INSTAMART\' else \'OTHERS\' END) Marketplace_Mapped FROM SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_db_sales_consolidated where not(lower(type) like \'%return%\' and lower(marketplace) like any (\'%shopify%\',\'%woocommerce%\'))) sc left join ( Select \"Store Seller Code on EasyEcom\" key , upper(\"Store Name\") store_name, \'EBO\' as ebo_Marketplace from sleepycat_db.maplemonk.sleepycat_db_ebo_metrics qualify row_number() over(partition by lower(trim(key)) order by 1) = 1 )eb on lower(trim(location_key)) = lower(trim(key)) where (lower(concat(reference_code,sku)) in ( ( select distinct lower(concat(reference_code,sku)) rf from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_EasyEcom_FACT_ITEMS where not(lower(ORDER_STATUS) like \'%cancel%\') and not(UPPER(replace(reference_code,\'_\',\'$\')) like any(\'E%\',\'%$E%\',\'R%\',\'%$R%\')) union (select distinct lower(concat(reference_code,sku)) from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_EasyEcom_FACT_ITEMS where (UPPER(replace(reference_code,\'_\',\'$\')) like any(\'E%\',\'%$E%\',\'R%\',\'%$R%\')) and lower(concat(SPLIT_PART(reference_code,\'_\',1),sku)) in ( select distinct lower(concat(reference_code,sku)) as sd from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_EasyEcom_FACT_ITEMS where not(UPPER(replace(reference_code,\'_\',\'$\')) like any(\'E%\',\'%$E%\',\'R%\',\'%$R%\')) and lower(ifnull(order_status,\'\')) like \'%cancel%\' ) ) ) ) ) or lower(type) like \'%return%\' ) a left join ( select * from (select sku_code , try_to_date(start_date,\'DD-MON-YY\') start_Date , try_to_date(end_date,\'DD-MON-YY\') End_date , try_to_double(replace(mrp,\',\',\'\')) mrp , try_to_double(replace(cogs,\',\',\'\')) cogs , div0(try_to_double(replace(gst,\'%\',\'\')),100) gst ,\'sales\' as TYPE , row_number() over (partition by sku_code, start_date, end_date order by mrp desc) rw from SLEEPYCAT_DB.MAPLEMONK.SKU_MRP_COGS ) where rw=1 ) d on lower(replace(d.sku_code,\' \',\'\')) = lower(replace(a.sku,\' \',\'\')) and to_date(a.order_date)::date >= d.start_date and to_date(a.order_date)::date <= d.end_date left join ( SELECT TO_DATE(start_date, \'DD/MM/YYYY\') AS START_DATE , TO_DATE(end_date, \'DD/MM/YYYY\') AS END_DATE, upper(marketplace) as MARKETPLACE, \'sales\' AS TYPE, REPLACE(\"Cost %\", \'%\', \'\')::float/100 AS otherShipmentCost FROM sleepycat_db.maplemonk.sleepycat_db_other_shipment_cost qualify row_number() over(partition by START_DATE,END_DATE,upper(marketplace) order by 1 ) = 1 ) osc on lower(a.FINAL_MARKETPLACE_shipment_costs) = lower(osc.MARKETPLACE) and to_date(a.order_date)::date >= osc.start_date and to_date(a.order_date)::date <= osc.end_date and lower(a.TYPE) = lower(osc.TYPE) left join ( SELECT TO_DATE(end_date, \'YYYY-MM-DD\') AS END_DATE, TO_DATE(start_date, \'YYYY-MM-DD\') AS START_DATE, upper(marketplace) as MARKETPLACE, \'sales\' AS TYPE, REPLACE(COMMISSION_VALUE, \'%\', \'\')::float/100 AS logisticCost FROM sleepycat_db.maplemonk.sleepycat_db_logistic_costs where marketplace is not null qualify row_number() over(partition by START_DATE,END_DATE,upper(marketplace) order by 1 ) = 1 ) a_c on lower(a.FINAL_MARKETPLACE) = lower(a_c.MARKETPLACE) and a.order_Date::date >= a_c.START_DATE and a.order_Date::date <= a_c.END_DATE and lower(a.TYPE) = lower(a_c.TYPE) left join ( SELECT TO_DATE(end_date, \'YYYY-MM-DD\') AS END_DATE, TO_DATE(start_date, \'YYYY-MM-DD\') AS START_DATE, upper(marketplace) as MARKETPLACE, \'sales\' AS TYPE, REPLACE(COMMISSION_VALUE, \'%\', \'\')::float/100 AS paymentgatewaycharges FROM sleepycat_db.maplemonk.sleepycat_db_payment_gateway_charges qualify row_number() over(partition by start_date,end_date,upper(marketplace) order by 1 ) = 1 ) pgc on trim(lower(a.FINAL_MARKETPLACE)) = trim(lower(pgc.MARKETPLACE)) and to_date(a.order_date)::date >= pgc.start_date and to_date(a.order_date)::date <= pgc.end_date and lower(a.TYPE) = lower(pgc.TYPE) left join ( select upper(marketplace) Marketplace, TO_DATE(end_date, \'YYYY-MM-DD\') AS END_DATE, TO_DATE(start_date, \'YYYY-MM-DD\') AS START_DATE, \'sales\' AS TYPE, upper(category) as Category, REPLACE(\"Original Commission_Value\", \'%\', \'\')::float/100 AS marketplaceCommission ,ifnull(REPLACE(\"price Start\", \',\', \'\')::float,0) as PriceStart ,ifnull(REPLACE(\"Price End\", \',\', \'\')::float,100000000000) as PriceEnd FROM sleepycat_db.maplemonk.sleepycat_db_marketplace_commissions where not(lower(marketplace) like any (\'%razor%\',\'%snap%\')) qualify row_number() over(partition by \"price Start\",\"Price End\",start_date,end_date,upper(marketplace),upper(category) order by 1 ) = 1 )mc on lower(a.FINAL_MARKETPLACE) = lower(mc.MARKETPLACE) and to_date(a.order_date)::date >= mc.start_date and to_date(a.order_date)::date <= mc.end_date and trim(lower(a.product_category)) = trim(lower(mc.category)) and lower(a.TYPE) = lower(mc.TYPE) and (div0(ifnull(a.total_mrp,0),ifnull(PRE_QUANTITY,0)) between PriceStart and PriceEnd) left join ( select upper(\"Store Seller Code on EasyEcom\") StoreCode, TO_DATE(to_date, \'YYYY-MM-DD\') AS END_DATE, TO_DATE(from_date, \'YYYY-MM-DD\') AS START_DATE, \'sales\' AS TYPE, case when last_day(TO_DATE(to_date, \'YYYY-MM-DD\')) = last_day(current_date) then div0(REPLACE(rent, \',\', \'\')::float,day(last_day(current_date))) * (day((current_date))-1) else REPLACE(rent, \',\', \'\')::float end AS EBO_Rent, case when last_day(TO_DATE(to_date, \'YYYY-MM-DD\')) = last_day(current_date) then div0(REPLACE(overhead, \',\', \'\')::float,day(last_day(current_date))) * (day((current_date))-1) else REPLACE(overhead, \',\', \'\')::float end AS EBO_overhead, case when last_day(TO_DATE(to_date, \'YYYY-MM-DD\')) = last_day(current_date) then div0(REPLACE(salary, \',\', \'\')::float,day(last_day(current_date))) * (day((current_date))-1) else REPLACE(salary, \',\', \'\')::float end AS EBO_salary, FROM sleepycat_db.maplemonk.sleepycat_db_ebo_metrics qualify row_number() over(partition by start_date,end_date,upper(StoreCode) order by 1 ) = 1 )ebo on lower(a.location_key) = lower(ebo.StoreCode) and to_date(a.order_date)::date >= ebo.start_date and to_date(a.order_date)::date <= ebo.end_date and lower(a.TYPE) = lower(ebo.TYPE) left join ( (Select date ,case when lower(channel) like \'%amazon%\' then \'AMAZON\' when lower(channel) like \'%flipkart%\' then \'FLIPKART\' when lower(channel) like any (\'%facebook%\',\'%google%\') then \'WEBSITE\' else upper(channel) end as Channel ,\'sales\' as TYPE ,sum(ifnull(spend,0)) spend from sleepycat_db.maplemonk.sleepycat_db_Marketing_Consolidated where not(lower(channel) like \'%flipkart%\') group by 1,2 ) UNION ALL (select start_time::date as Date ,\'FLIPKART\' as Channel ,\'SALES\' as Type ,sum(ifnull(CAMPAIGN_SPEND,0)) Sped from sleepycat_db.maplemonk.sleepycatdb_new_flipkart_ads_fact_items group by 1 ) )p_sp on p_sp.date = a.order_date and lower(p_sp.channel) = lower(a.FINAL_Mapped_Marketplace) and lower(a.type) = lower(p_sp.type);",
